55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	/** The MHPCO's catalogue of insurable items. Base premium and insurance value are
60	 *  independent figures; they are listed together because they describe one item type. */
61	const ITEM_CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
62	  sword: { basePremium: 100, insuranceValue: 1000 },
63	  amulet: { basePremium: 60, insuranceValue: 600 },
64	  staff: { basePremium: 80, insuranceValue: 800 },
65	  potion: { basePremium: 40, insuranceValue: 400 },
66	  rune: { basePremium: 25, insuranceValue: 250 },
67	  moonstone: { basePremium: 25, insuranceValue: 250 },
68	};
69	
70	const itemBasePremium = (item: Item): number => ITEM_CATALOGUE[item.type].basePremium;
71	
72	const BLOCK_SIZE = 3;
73	const BLOCK_BASE_PREMIUM = 60;
74	
75	const sumOfItemBasePremiums = (items: Item[]): number =>
76	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
77	
78	const itemsGroupedByType = (items: Item[]): Item[][] => {
79	  const byType = new Map<string, Item[]>();
80	  for (const item of items) {
81	    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
82	  }
83	  return [...byType.values()];
84	};
85	
86	const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;
87	
88	const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
89	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);
90	
91	const policyBasePremium = (items: Item[]): number =>
92	  itemsGroupedByType(items).reduce(
93	    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
94	    0,
95	  );
96	
97	const withFirstInsuranceSurcharge = (policyBase: number): number =>
98	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
99	
100	const roundPremiumInMHPCOsFavor = Math.ceil;
101	
102	const HIGH_ENCHANTMENT_THRESHOLD = 5;
103	
104	const isCursed = (item: Item): boolean => item.cursed === true;
105	
106	const isHighlyEnchanted = (item: Item): boolean =>
107	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
108	
109	interface RiskSurcharge {
110	  appliesTo: (item: Item) => boolean;
111	  rateOfBasePremium: number;
112	}
113	
114	const RISK_SURCHARGES: RiskSurcharge[] = [
115	  { appliesTo: isCursed, rateOfBasePremium: 0.5 },
116	  { appliesTo: isHighlyEnchanted, rateOfBasePremium: 0.3 },
117	];
118	
119	const itemRiskSurcharge = (item: Item): number =>
120	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
121	    (sum, surcharge) => sum + itemBasePremium(item) * surcharge.rateOfBasePremium,
122	    0,
123	  );
124	
125	const totalRiskSurcharges = (items: Item[]): number =>
126	  items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
127	
128	/** Who the policy is for, and where it sits in their history with the MHPCO. */
129	interface QuoteContext {
130	  customer: Customer;
131	  isFollowUpContract: boolean;
132	}
133	
134	const LOYALTY_DISCOUNT = 0.2;
135	const LOYALTY_THRESHOLD_YEARS = 2;
136	
137	const isLoyal = (context: QuoteContext): boolean =>
138	  context.customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
139	
140	const loyaltyDiscount = (policyBase: number, context: QuoteContext): number =>
141	  isLoyal(context) ? policyBase * LOYALTY_DISCOUNT : 0;
142	
143	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
144	
145	const followUpContractDiscount = (policyBase: number, context: QuoteContext): number =>
146	  context.isFollowUpContract ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
147	
148	const policyWidePremium = (policyBase: number, context: QuoteContext): number =>
149	  withFirstInsuranceSurcharge(policyBase) -
150	  loyaltyDiscount(policyBase, context) -
151	  followUpContractDiscount(policyBase, context);
152	
153	const premiumBeforeFee = (items: Item[], context: QuoteContext): number =>
154	  policyWidePremium(policyBasePremium(items), context) + totalRiskSurcharges(items);
155	
156	const quotePremium = (items: Item[], context: QuoteContext): number =>
157	  roundPremiumInMHPCOsFavor(premiumBeforeFee(items, context) + PROCESSING_FEE);
158	
159	const DEDUCTIBLE_PER_DAMAGE = 100;
160	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
161	
162	const itemInsuranceValue = (item: Item): number => ITEM_CATALOGUE[item.type].insuranceValue;
163	
164	const insuranceSum = (items: Item[]): number =>
165	  items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
166	
167	interface Policy {
168	  items: Item[];
169	  remainingCap: number;
170	}
171	
172	const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
173	const HALF_REIMBURSEMENT_RATE = 0.5;
174	
175	const isVeryHighlyEnchanted = (item: Item): boolean =>
176	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT;
177	
178	const reimbursableDamage = (damage: Damage, damagedItem: Item): number =>
179	  isVeryHighlyEnchanted(damagedItem)
180	    ? damage.amount * HALF_REIMBURSEMENT_RATE
181	    : damage.amount;
182	
183	const damagePayout = (damage: Damage, damagedItem: Item): number =>
184	  reimbursableDamage(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
185	
186	const incidentPayout = (incident: Incident, insuredItems: Item[]): number =>
187	  incident.damages.reduce((sum, damage) => {
188	    const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
189	    if (damagedItem === undefined) {
190	      throw new Error(`Item not covered by policy: ${damage.itemType}`);
191	    }
192	    return sum + damagePayout(damage, damagedItem);
193	  }, 0);
194	
195	/** A claim draws down the policy's remaining cap, so settling one yields a new policy state. */
196	const settleClaim = (policy: Policy, incident: Incident): [ClaimResult, Policy] => {
197	  const payout = incidentPayout(incident, policy.items);
198	  const remainingCap = policy.remainingCap - payout;
199	  return [{ payout, remainingCap }, { ...policy, remainingCap }];
200	};
201	
202	const openPolicy = (items: Item[]): Policy => ({
203	  items,
204	  remainingCap: insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
205	});
206	
207	const findPolicy = (policies: Map<number, Policy>, policyRef: number): Policy => {
208	  const policy = policies.get(policyRef);
209	  if (policy === undefined) {
210	    throw new Error(`Unknown policy: ${policyRef}`);
211	  }
212	  return policy;
213	};
214	
215	export const runScenario = (scenario: Scenario): ScenarioResult => {
216	  const policies = new Map<number, Policy>();
217	  let quotesSoFar = 0;
218	
219	  const runStep = (step: Step, stepIndex: number): StepResult => {
220	    if (step.op === "quote") {
221	      policies.set(stepIndex, openPolicy(step.items));
222	      const context = {
223	        customer: scenario.customer,
224	        isFollowUpContract: quotesSoFar > 0,
225	      };
226	      quotesSoFar += 1;
227	      return { premium: quotePremium(step.items, context) };
228	    }
229	
230	    const [result, settledPolicy] = settleClaim(
231	      findPolicy(policies, step.policy),
232	      step.incident,
233	    );
234	    policies.set(step.policy, settledPolicy);
235	    return result;
236	  };
237	
238	  return { results: scenario.steps.map(runStep) };
239	};
